BEGIN IMMEDIATE; PRAGMA defer_foreign_keys=ON;
CREATE TABLE execution_attempts_v2 (attempt_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES workflow_runs(run_id), workflow_id TEXT NOT NULL, command_id TEXT NOT NULL REFERENCES workflow_commands(command_id) DEFERRABLE INITIALLY DEFERRED, kind TEXT NOT NULL CHECK(kind IN('AGENT','PROCESS')), experiment_id TEXT, execution_id TEXT, attempt_ordinal INTEGER NOT NULL CHECK(attempt_ordinal>0), host_generation TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('OPEN','CLOSED')), started_at REAL NOT NULL, ended_at REAL, terminal_reason TEXT CHECK(terminal_reason IS NULL OR terminal_reason IN('SUCCEEDED','FAILED','TIMED_OUT','CANCELLED','LOST')), process_group_id INTEGER CHECK(process_group_id IS NULL OR process_group_id>0), observation_json TEXT CHECK(observation_json IS NULL OR json_valid(observation_json,1)), CHECK(attempt_id<>'' AND workflow_id<>'' AND host_generation<>''), CHECK((kind='AGENT' AND experiment_id IS NULL AND execution_id IS NULL) OR (kind='PROCESS' AND experiment_id IS NOT NULL AND execution_id IS NOT NULL)), CHECK((state='OPEN' AND ended_at IS NULL AND terminal_reason IS NULL AND (observation_json IS NULL OR (kind='AGENT' AND json_type(observation_json,'$.request')='object'))) OR (state='CLOSED' AND ended_at IS NOT NULL AND terminal_reason IS NOT NULL AND observation_json IS NOT NULL))) STRICT;
INSERT INTO execution_attempts_v2 SELECT * FROM execution_attempts;
DROP TABLE execution_attempts;
ALTER TABLE execution_attempts_v2 RENAME TO execution_attempts;
CREATE UNIQUE INDEX execution_agent_attempt_ordinal ON execution_attempts(workflow_id,command_id,attempt_ordinal) WHERE kind='AGENT' AND execution_id IS NULL; CREATE UNIQUE INDEX execution_process_attempt_ordinal ON execution_attempts(workflow_id,command_id,execution_id,attempt_ordinal) WHERE kind='PROCESS' AND execution_id IS NOT NULL;
CREATE UNIQUE INDEX execution_one_open_agent_attempt ON execution_attempts(workflow_id,command_id) WHERE kind='AGENT' AND state='OPEN' AND execution_id IS NULL; CREATE UNIQUE INDEX execution_one_open_process_attempt ON execution_attempts(workflow_id,command_id,execution_id) WHERE kind='PROCESS' AND state='OPEN' AND execution_id IS NOT NULL;
CREATE TRIGGER immutable_attempt_delete BEFORE DELETE ON execution_attempts BEGIN SELECT RAISE(ABORT,'execution attempts are durable observations'); END;
CREATE TRIGGER execution_attempt_update_rules BEFORE UPDATE ON execution_attempts WHEN OLD.state<>'OPEN' OR NOT((NEW.state='OPEN' AND OLD.process_group_id IS NULL AND NEW.process_group_id>0 AND NEW.ended_at IS NULL AND NEW.terminal_reason IS NULL AND NEW.observation_json IS OLD.observation_json) OR (NEW.state='CLOSED' AND (OLD.process_group_id IS NEW.process_group_id OR OLD.process_group_id IS NULL) AND (OLD.kind<>'AGENT' OR OLD.observation_json IS NULL OR json_extract(NEW.observation_json,'$.request')=json_extract(OLD.observation_json,'$.request')))) OR OLD.attempt_id<>NEW.attempt_id OR OLD.run_id<>NEW.run_id OR OLD.workflow_id<>NEW.workflow_id OR OLD.command_id<>NEW.command_id OR OLD.kind<>NEW.kind OR OLD.attempt_ordinal<>NEW.attempt_ordinal OR OLD.host_generation<>NEW.host_generation OR OLD.experiment_id IS NOT NEW.experiment_id OR OLD.execution_id IS NOT NEW.execution_id OR OLD.started_at<>NEW.started_at BEGIN SELECT RAISE(ABORT,'attempt permits one process bind and one OPEN to CLOSED update'); END;
INSERT INTO schema_migrations(version) VALUES(2); PRAGMA user_version=2; COMMIT;
